            style={{ padding: "6px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label htmlFor="end-date" style={{ marginRight: "8px", fontWeight: "bold" }}>End Date:</label>
          <input 
            type="date" 
            id="end-date" 
            data-testid="end-date" 
